<script setup lang="ts">
import {computed,inject,onBeforeUnmount,ref,watch,type ComputedRef} from 'vue';
import {onBeforeRouteLeave,onBeforeRouteUpdate} from 'vue-router';
import {CheckCircle2,Database,LoaderCircle,RefreshCw,Save,ShieldCheck} from 'lucide-vue-next';
import type {DatasetConfigurationState,DatasetConfigurationTable,DatasetConfigurationResult,RepositoryPermissions} from '@oxen/shared';
import {post,queryString,request} from '../api';
import {useAppStore} from '../stores/app';
const props=defineProps<{base:string;branch:string}>(),emit=defineEmits<{configured:[]}>(),app=useAppStore();
const permissions=inject<ComputedRef<RepositoryPermissions>>('repositoryPermissions');
const state=ref<DatasetConfigurationState>(),table=ref<DatasetConfigurationTable>(),result=ref<DatasetConfigurationResult>(),selected=ref(''),readme=ref(''),identity=ref(''),attachmentFields=ref<string[]>([]),loading=ref(false),inspecting=ref(false),busy=ref(false),error=ref('');let generation=0,inspection=0;
const dirty=computed(()=>!!selected.value&&!result.value&&!state.value?.configured),allowed=computed(()=>state.value?.canConfigure===true&&!state.value.configured&&permissions?.value.capabilities?.['data.edit']===true&&permissions.value.capabilities?.['tasks.manage']===true),ready=computed(()=>allowed.value&&!!table.value&&table.value.path===selected.value&&table.value.commitId===state.value?.commitId&&!!identity.value&&!loading.value&&!inspecting.value&&!busy.value);
async function mayLeave(){if(busy.value){app.notify('正在提交数据集配置，请等待回读结果。');return false;}if(!dirty.value)return true;const ok=await app.confirmAction('数据集入口配置尚未提交，确认放弃本次选择吗？',{title:'未提交的配置',confirmLabel:'放弃选择'});if(ok){selected.value='';table.value=undefined;}return ok;}
const unregister=app.registerDraftGuard(mayLeave);onBeforeRouteLeave(mayLeave);onBeforeRouteUpdate((to,from)=>to.fullPath===from.fullPath||mayLeave());
function unload(event:BeforeUnloadEvent){if(dirty.value||busy.value){event.preventDefault();event.returnValue='';}}window.addEventListener('beforeunload',unload);onBeforeUnmount(()=>{generation++;inspection++;unregister();window.removeEventListener('beforeunload',unload);});
async function load(){const current=++generation;++inspection;loading.value=true;inspecting.value=false;error.value='';state.value=undefined;table.value=undefined;result.value=undefined;selected.value='';identity.value='';attachmentFields.value=[];try{const value=await request<DatasetConfigurationState>(props.base+'/dataset-configuration'+queryString({ref:props.branch}));if(current!==generation)return;state.value=value;readme.value=value.readmes.find(file=>file.path==='README.md')?.path??value.readmes[0]?.path??'';}catch(cause){if(current===generation)error.value=(cause as Error).message;}finally{if(current===generation)loading.value=false;}}
async function choose(){const current=++inspection,context=generation;table.value=undefined;identity.value='';attachmentFields.value=[];error.value='';if(!selected.value)return;inspecting.value=true;try{const value=await request<DatasetConfigurationTable>(props.base+'/dataset-configuration/table'+queryString({ref:state.value!.commitId,path:selected.value}));if(current!==inspection||context!==generation)return;table.value=value;identity.value=value.fields.find(field=>field.name==='id'&&field.uniqueIdentity)?.name??value.fields.find(field=>field.uniqueIdentity)?.name??'';}catch(cause){if(current===inspection&&context===generation)error.value=(cause as Error).message;}finally{if(current===inspection&&context===generation)inspecting.value=false;}}
async function refresh(){if(await mayLeave())await load();}
async function save(){if(!ready.value||!state.value||!table.value)return;const current=generation,captured=state.value,source=table.value;if(!await app.confirmAction(`固定分支 ${props.branch} 的 ${source.path} 为完整逻辑数据集入口，共 ${source.totalRows} 条。此操作写入一次版本配置，保留原文件、真值与历史标签；之后不能在此更换入口。`,{title:'确认一次性数据集配置',confirmLabel:'提交并验证'}))return;if(current!==generation)return;busy.value=true;error.value='';try{const value=await post<DatasetConfigurationResult>(props.base+'/dataset-configuration',{ref:props.branch,expectedCommit:captured.commitId,path:source.path,...(readme.value?{readmePath:readme.value}:{}),identityField:identity.value,attachmentFields:attachmentFields.value});if(current!==generation)return;result.value=value;selected.value='';state.value={...captured,commitId:value.commitId,configured:true,canConfigure:false,reason:'该分支已提交数据集配置。'};app.notify('数据集入口已配置并通过固定版本回读');emit('configured');}catch(cause){if(current===generation)error.value=(cause as Error).message;}finally{if(current===generation)busy.value=false;}}
watch(()=>[props.base,props.branch],load,{immediate:true});
</script>
<template><section class="dataset-configuration panel"><header><Database :size="21"/><div><h3>数据集配置</h3><p>旧项目由负责人明确一次规范入口，数据编辑随后按当前分支自动加载完整逻辑数据集。</p></div><button class="btn btn-ghost" :disabled="loading||busy" @click="refresh"><RefreshCw :size="15"/>刷新</button></header><div v-if="loading" class="empty"><LoaderCircle class="spin" :size="24"/>读取固定版本与真实文件…</div><template v-else-if="state"><p class="configuration-version">分支 {{branch}} <code>{{state.commitId}}</code></p><div v-if="result" class="configuration-success"><CheckCircle2 :size="23"/><div><strong>配置已提交并验证</strong><p>{{result.path}} · {{result.totalRows}} 条样本 · {{result.attachmentCount}} 个关联附件</p><code>{{result.commitId}}</code><p v-for="warning in result.warnings" :key="warning">{{warning}}</p><p>返回“数据编辑”即可自动打开此分支的数据集。</p></div></div><div v-else-if="state.configured" class="configuration-notice"><ShieldCheck :size="20"/><p>{{state.reason}} 已有规范入口、身份与原始真值继续保持。</p></div><form v-else @submit.prevent="save"><p v-if="!allowed" class="configuration-notice"><ShieldCheck :size="19"/>当前身份仅可查看。提交配置同时需要数据编辑与任务管理能力，并选择实际分支。</p><fieldset :disabled="!allowed||busy"><label>规范样本入口<select v-model="selected" :disabled="loading||inspecting" @change="choose"><option value="">选择当前固定版本中的表格</option><option v-for="file in state.tables" :key="file.path" :value="file.path">{{file.path}} · {{(file.size/1024).toFixed(1)}} KB</option></select><small>支持 CSV、TSV、JSONL；策略、元数据和原始归档目录不会作为候选。</small></label><p v-if="!state.tables.length" class="configuration-notice">没有符合条件的表格，请先通过受控导入建立项目数据。</p><div v-if="inspecting" class="configuration-notice"><LoaderCircle class="spin" :size="17"/>校验完整表格字段与身份唯一性…</div><template v-if="table"><div class="configuration-table-meta"><strong>{{table.totalRows}} 条完整样本</strong><span>{{table.fields.length}} 个字段</span><code>SHA256 {{table.sha256}}</code></div><label>业务身份字段<select v-model="identity"><option value="">选择逐条唯一且非空的字段</option><option v-for="field in table.fields.filter(field=>field.uniqueIdentity)" :key="field.name" :value="field.name">{{field.name}} · {{field.type}}</option></select><small>必须逐条唯一；仅锁定已有字段，沿用历史稳定行 ID，不重写原始字段或标签关联。</small></label><p v-if="!table.fields.some(field=>field.uniqueIdentity)" class="configuration-notice">当前表格没有有效唯一身份字段，无法在此直接配置；请由负责人整理源数据后重试。</p><label>README 说明文件<select v-model="readme"><option v-if="!state.readmes.length" value="">无 README，保留空说明</option><option v-for="file in state.readmes" :key="file.path" :value="file.path">{{file.path}}</option></select></label><div class="configuration-attachment"><h4>附件字段映射</h4><p>选择记录中保存仓库相对文件路径的字段。每个非空值必须指向当前版本中真实存在的普通文件；不会执行附件内容。</p><div><label v-for="field in table.fields" :key="field.name"><input v-model="attachmentFields" type="checkbox" :value="field.name"/>{{field.name}}</label></div></div></template></fieldset><details><summary>配置和容量边界</summary><p>仅适用于尚无导入清单、数据集描述和新版标注格式的旧项目。JSONL 最多64MiB，CSV/TSV 最多25MiB，最多250000条、1000列。只新增描述与稳定身份映射并生成一个提交；标签规范、已有赋值与原始文件保留。</p></details><footer><button class="btn btn-primary" :disabled="!ready"><LoaderCircle v-if="busy" class="spin" :size="16"/><Save v-else :size="16"/>{{busy?'提交并回读验证中…':'保存一次性配置'}}</button></footer></form></template><p v-if="error" class="error-state" role="alert">{{error}}</p></section></template>
<style scoped>
.dataset-configuration{padding:24px}.dataset-configuration>header{display:flex;gap:12px;align-items:flex-start;margin-bottom:20px}.dataset-configuration>header>svg{color:var(--primary);margin-top:3px;flex-shrink:0}.dataset-configuration h3{font-size:18px}.dataset-configuration header p{font-size:13px;color:var(--muted);line-height:1.8;margin-top:8px}.dataset-configuration header .btn{margin-left:auto}.configuration-version{font-size:13px;color:var(--muted);line-height:1.8;margin-bottom:20px}.configuration-version code{display:block;font-size:12px;overflow-wrap:anywhere}.dataset-configuration fieldset{border:0;padding:0;min-width:0}.dataset-configuration fieldset>label{display:flex;flex-direction:column;gap:10px;font-size:14px;margin:22px 0}.dataset-configuration select{background:var(--surface);color:var(--text);border:1px solid var(--line);border-radius:6px;min-height:40px;font-size:14px;padding:9px 12px}.dataset-configuration select:focus{outline:2px solid color-mix(in srgb,var(--primary) 45%,transparent)}.dataset-configuration small,.configuration-attachment p{font-size:12px;color:var(--muted);line-height:1.9}.configuration-table-meta{border:1px solid var(--line);background:var(--surface-raised);border-radius:6px;padding:16px;display:flex;gap:18px;flex-wrap:wrap;font-size:13px}.configuration-table-meta code{font-size:11px;overflow-wrap:anywhere;width:100%;color:var(--muted)}.configuration-attachment{margin:22px 0}.configuration-attachment h4{font-size:14px;margin-bottom:9px}.configuration-attachment>div{display:flex;gap:15px;flex-wrap:wrap;margin-top:15px}.configuration-attachment label{display:flex;gap:7px;align-items:center;font-size:13px}.configuration-attachment input{accent-color:var(--primary)}.configuration-notice,.configuration-success{display:flex;gap:12px;align-items:start;padding:17px;border:1px solid var(--line);border-radius:6px;background:var(--surface-raised);font-size:13px;line-height:1.9;margin:17px 0}.configuration-notice svg,.configuration-success svg{flex-shrink:0;margin-top:3px}.configuration-success svg{color:var(--success)}.configuration-success strong{font-size:15px}.configuration-success p{margin:8px 0;color:var(--muted)}.configuration-success code{font-size:12px;overflow-wrap:anywhere}.dataset-configuration details{font-size:12px;color:var(--muted);line-height:1.9;border-top:1px solid var(--line);padding-top:16px}.dataset-configuration summary{cursor:pointer}.dataset-configuration details p{margin-top:10px}.dataset-configuration footer{display:flex;justify-content:flex-end;margin-top:22px;padding-top:19px;border-top:1px solid var(--line)}.dataset-configuration .empty{gap:12px;padding:45px}.dataset-configuration .error-state{margin-top:18px}.spin{animation:spin 1s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}@media(max-width:700px){.dataset-configuration{padding:18px}.dataset-configuration>header{flex-wrap:wrap}.dataset-configuration header .btn{margin-left:0}}
</style>
